(function(){'use strict';var container=document.querySelector('.mw-mc-container');if(!container)return;if(container.dataset.pullRefreshInstalled)return;container.dataset.pullRefreshInstalled='1';var THRESHOLD=80;var MAX_PULL=120;var loader=document.createElement('div');loader.className='mw-mc-pull-loader';loader.innerHTML='<div class="mw-mc-pull-spinner" aria-hidden="true">'+'<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">'+'<polyline points="23 4 23 10 17 10"/>'+'<path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/>'+'</svg>'+'</div>'+'<span class="mw-mc-pull-label">Pull to refresh</span>';container.insertBefore(loader,container.firstChild);var startY=0;var pullY=0;var active=!1;var triggered=!1;function atTop(){return window.scrollY<=0&&container.scrollTop<=0}
function setLoaderHeight(px){loader.style.height=px+'px'}
function markTriggered(yes){if(yes===triggered)return;triggered=yes;if(yes){loader.classList.add('mw-mc-pull-ready');loader.querySelector('.mw-mc-pull-label').textContent='Release to refresh';if(window.MwHaptics)window.MwHaptics.selection();}else{loader.classList.remove('mw-mc-pull-ready');loader.querySelector('.mw-mc-pull-label').textContent='Pull to refresh'}}
container.addEventListener('touchstart',function(e){if(!atTop())return;active=!0;triggered=!1;startY=e.touches[0].clientY;loader.classList.add('mw-mc-pull-tracking')},{passive:!0});container.addEventListener('touchmove',function(e){if(!active)return;var delta=e.touches[0].clientY-startY;if(delta<=0){pullY=0;setLoaderHeight(0);return}
pullY=Math.min(MAX_PULL,delta*0.6);setLoaderHeight(pullY);markTriggered(pullY>=THRESHOLD)},{passive:!0});container.addEventListener('touchend',function(){if(!active)return;active=!1;loader.classList.remove('mw-mc-pull-tracking');if(triggered){loader.classList.add('mw-mc-pull-loading');loader.querySelector('.mw-mc-pull-label').textContent='Refreshing…';setLoaderHeight(60);setTimeout(function(){window.location.reload()},250)}else{loader.style.transition='height 200ms cubic-bezier(0.2, 0.8, 0.2, 1)';setLoaderHeight(0);setTimeout(function(){loader.style.transition='';markTriggered(!1)},220)}},{passive:!0});container.addEventListener('touchcancel',function(){active=!1;triggered=!1;setLoaderHeight(0);loader.classList.remove('mw-mc-pull-tracking','mw-mc-pull-ready','mw-mc-pull-loading')},{passive:!0})}())